from collections import deque

def is_empty(board, N):
    return all(board[r][c] == 0 for r in range(N) for c in range(N))

def is_cleared(board, N):
    return all(board[r][c] == 0 for r in range(N) for c in range(N))

def apply_tromino(board, N, r, c):
    # Fixed L-tromino: (r, c), (r+1, c), (r, c+1)
    if r + 1 >= N or c + 1 >= N:
        return None # Out of bounds

    new_board = [row[:] for row in board]
    if new_board[r][c] == 0 and new_board[r+1][c] == 0 and new_board[r][c+1] == 0:
        new_board[r][c] = 1
        new_board[r+1][c] = 1
        new_board[r][c+1] = 1
        return new_board
    return None

def apply_row_clear(board, N, r):
    new_board = [row[:] for row in board]
    if all(new_board[r][c] == 1 for c in range(N)):
        for c in range(N):
            new_board[r][c] = 0
        return new_board
    return None

def apply_col_clear(board, N, c):
    new_board = [row[:] for row in board]
    if all(new_board[r][c] == 1 for r in range(N)):
        for r in range(N):
            new_board[r][c] = 0
        return new_board
    return None

def find_next_states(board, N):
    next_states = []

    # 1. Tromino Placement Moves
    for r in range(N - 1):
        for c in range(N - 1):
            new_board = apply_tromino(board, N, r, c)
            if new_board:
                next_states.append(new_board)

    # 2. Row Clear Moves
    for r in range(N):
        new_board = apply_row_clear(board, N, r)
        if new_board:
            next_states.append(new_board)

    # 3. Column Clear Moves
    for c in range(N):
        new_board = apply_col_clear(board, N, c)
        if new_board:
            next_states.append(new_board)

    return next_states

def solve_n3():
    N = 3
    initial_state = [[0] * N for _ in range(N)]

    # BFS setup
    queue = deque([(initial_state, [])]) # (board, path)
    visited = {tuple(map(tuple, initial_state))}

    print(f"--- N=3 Investigation ---")
    print("Starting BFS search for a clearing sequence (max depth 10)...")

    while queue:
        current_board, path = queue.popleft()

        if is_cleared(current_board, N):
            print("\nSUCCESS: Board cleared!")
            print("Move Sequence Length:", len(path))
            # Outputting the sequence is too verbose, but we confirm possibility
            return True, path

        if len(path) >= 10: # Depth limit to prevent infinite loop/excessive computation
            continue

        next_states = find_next_states(current_board, N)

        for next_board in next_states:
            board_tuple = tuple(map(tuple, next_board))
            if board_tuple not in visited:
                visited.add(board_tuple)
                new_path = path + [next_board]
                queue.append((next_board, new_path))

    print("\nFAILURE: No clearing sequence found within the depth limit (10 moves).")
    return False, None

possible_n3, path_n3 = solve_n3()

